import json

with open('output/charts.json') as f:
    charts = json.load(f)

with open('output/report_data.json') as f:
    data = json.load(f)

kpis = data['kpis']

# Helper for formatting
def fmt_money(v):
    return f"${v:,.0f}"

def fmt_pct(v):
    return f"{v:.1f}%"

# Build HTML report
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Chocolate Retail Sales Performance Report (2023–2024)</title>
<style>
  :root {{
    --primary: #2E5C8A;
    --secondary: #D4A373;
    --accent: #5A7D5A;
    --danger: #C0392B;
    --bg: #F7F9FB;
    --card: #FFFFFF;
    --text: #1F2937;
    --text-light: #6B7280;
    --border: #E5E7EB;
  }}
  * {{ box-sizing: border-box; }}
  body {{
    margin: 0;
    font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }}
  .container {{
    max-width: 1200px;
    margin: 0 auto;
    padding: 32px 24px;
  }}
  header {{
    border-bottom: 3px solid var(--primary);
    padding-bottom: 16px;
    margin-bottom: 32px;
  }}
  header h1 {{
    margin: 0 0 8px;
    font-size: 1.9rem;
    color: var(--primary);
  }}
  header p {{
    margin: 0;
    color: var(--text-light);
    font-size: 0.95rem;
  }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 32px;
  }}
  .kpi-card {{
    background: var(--card);
    border-radius: 10px;
    padding: 20px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.06);
    border-left: 5px solid var(--primary);
    transition: transform .15s ease;
  }}
  .kpi-card:hover {{ transform: translateY(-2px); }}
  .kpi-card .label {{
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-light);
    margin-bottom: 6px;
  }}
  .kpi-card .value {{
    font-size: 1.6rem;
    font-weight: 700;
    color: var(--primary);
  }}
  .kpi-card .sub {{
    font-size: 0.8rem;
    color: var(--text-light);
    margin-top: 4px;
  }}
  section {{
    background: var(--card);
    border-radius: 10px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.06);
  }}
  section h2 {{
    margin-top: 0;
    font-size: 1.25rem;
    color: var(--primary);
    border-bottom: 2px solid var(--border);
    padding-bottom: 8px;
    margin-bottom: 16px;
  }}
  section h3 {{
    margin-top: 20px;
    font-size: 1.05rem;
    color: var(--text);
  }}
  .chart {{
    width: 100%;
    margin: 16px 0;
    border-radius: 8px;
    overflow: hidden;
  }}
  .chart img {{
    width: 100%;
    height: auto;
    display: block;
  }}
  .two-col {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(420px, 1fr));
    gap: 20px;
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    font-size: 0.9rem;
  }}
  th, td {{
    padding: 10px 12px;
    text-align: left;
    border-bottom: 1px solid var(--border);
  }}
  th {{
    background: #F3F4F6;
    font-weight: 600;
    color: var(--text);
  }}
  tr:hover {{ background: #F9FAFB; }}
  .insight {{
    background: #EFF6FF;
    border-left: 4px solid var(--primary);
    padding: 12px 16px;
    border-radius: 6px;
    margin-top: 12px;
    font-size: 0.95rem;
  }}
  .insight strong {{ color: var(--primary); }}
  .muted {{ color: var(--text-light); font-size: 0.9rem; }}
  footer {{
    text-align: center;
    color: var(--text-light);
    font-size: 0.85rem;
    padding: 24px 0 40px;
  }}
  @media (max-width: 600px) {{
    .two-col {{ grid-template-columns: 1fr; }}
    header h1 {{ font-size: 1.4rem; }}
  }}
</style>
</head>
<body>
<div class="container">
  <header>
    <h1>Chocolate Retail Sales Performance Report</h1>
    <p>2023–2024 Fiscal Period &nbsp;|&nbsp; Prepared for Retail Management &nbsp;|&nbsp; Data-Driven Strategic Insights</p>
  </header>

  <!-- Executive Summary KPIs -->
  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="label">Total Revenue</div>
      <div class="value">{fmt_money(kpis['total_revenue'])}</div>
      <div class="sub">Across 50,000 transactions</div>
    </div>
    <div class="kpi-card">
      <div class="label">Total Profit</div>
      <div class="value">{fmt_money(kpis['total_profit'])}</div>
      <div class="sub">{fmt_pct(kpis['total_profit']/kpis['total_revenue']*100)} of revenue</div>
    </div>
    <div class="kpi-card">
      <div class="label">Avg Profit Margin</div>
      <div class="value">{fmt_pct(kpis['avg_profit_margin'])}</div>
      <div class="sub">Per transaction average</div>
    </div>
    <div class="kpi-card">
      <div class="label">Avg Order Value</div>
      <div class="value">${kpis['avg_order_value']:.2f}</div>
      <div class="sub">Mean revenue per order</div>
    </div>
    <div class="kpi-card">
      <div class="label">Discount Utilization</div>
      <div class="value">{fmt_pct(kpis['discount_utilization'])}</div>
      <div class="sub">Orders with any discount</div>
    </div>
  </div>

  <!-- Sales Trends Over Time -->
  <section>
    <h2>Sales Trends Over Time</h2>
    <p class="muted">Monthly and quarterly revenue and order volume trends across 2023 and 2024, highlighting seasonality and growth patterns.</p>
    <div class="chart"><img src="data:image/png;base64,{charts['monthly_trend']}" alt="Monthly Revenue and Order Volume"></div>
    <div class="insight"><strong>Insight:</strong> Revenue follows a fairly consistent monthly cadence with notable peaks around holiday seasons (Q4). Order volume closely tracks revenue, indicating stable average order values month-to-month.</div>

    <h3>Quarterly Year-over-Year Comparison</h3>
    <div class="chart"><img src="data:image/png;base64,{charts['quarterly_yoy']}" alt="Quarterly Revenue YoY"></div>
    <div class="insight"><strong>Insight:</strong> Q4 remains the strongest quarter in both years. 2024 shows modest growth over 2023 across most quarters, suggesting steady business expansion.</div>

    <h3>Profit Margin Trend</h3>
    <div class="chart"><img src="data:image/png;base64,{charts['monthly_margin']}" alt="Monthly Profit Margin Trend"></div>
    <div class="insight"><strong>Insight:</strong> Profit margins remain relatively stable around the ~40% average, with minor seasonal dips during high-discount promotional periods.</div>
  </section>

  <!-- Product & Category Performance -->
  <section>
    <h2>Product & Category Performance</h2>
    <p class="muted">Evaluation of top-performing products by revenue and profit. <em>Note: Detailed product attributes (brand, category, cocoa percentage) are not present in the provided dataset and would require joining with dimension tables for deeper analysis.</em></p>
    <div class="chart"><img src="data:image/png;base64,{charts['top_products']}" alt="Top 15 Products by Revenue"></div>
    <div class="insight"><strong>Insight:</strong> The top 15 products drive a significant share of total revenue. Concentration among leading SKUs suggests strong star products that should be prioritized for inventory and marketing investment.</div>
    <h3>Top 10 Products Summary</h3>
    <table>
      <tr><th>Product</th><th>Revenue</th><th>Profit</th><th>Margin</th><th>Orders</th></tr>
'''

for row in data['top_products']:
    html += f'      <tr><td>{row["product_id"]}</td><td>${row["revenue"]:,.0f}</td><td>${row["profit"]:,.0f}</td><td>{row["profit_margin"]:.1f}%</td><td>{row["orders"]:,}</td></tr>\n'

html += f'''    </table>
  </section>

  <!-- Store & Geographic Performance -->
  <section>
    <h2>Store & Geographic Performance</h2>
    <p class="muted">Comparison of sales performance across store locations. <em>Note: Store metadata (city, country, store type) is not present in the provided dataset and would require joining with the stores dimension table for geographic and format benchmarking.</em></p>
    <div class="chart"><img src="data:image/png;base64,{charts['top_stores']}" alt="Top 15 Stores by Revenue"></div>
    <div class="insight"><strong>Insight:</strong> A subset of stores significantly outperforms others, indicating potential best practices in operations, location, or local marketing that could be replicated across the network.</div>
    <h3>Top 10 Stores Summary</h3>
    <table>
      <tr><th>Store</th><th>Revenue</th><th>Profit</th><th>Orders</th></tr>
'''

for row in data['top_stores']:
    html += f'      <tr><td>{row["store_id"]}</td><td>${row["revenue"]:,.0f}</td><td>${row["profit"]:,.0f}</td><td>{row["orders"]:,}</td></tr>\n'

html += f'''    </table>
  </section>

  <!-- Discount Impact & Profitability Analysis -->
  <section>
    <h2>Discount Impact & Profitability Analysis</h2>
    <p class="muted">Assessment of how discount levels affect revenue, profit margins, and order quantities to evaluate promotional effectiveness.</p>
    <div class="two-col">
      <div class="chart"><img src="data:image/png;base64,{charts['discount_impact']}" alt="Discount Impact"></div>
      <div class="chart"><img src="data:image/png;base64,{charts['discount_pie']}" alt="Revenue Share by Discount"></div>
    </div>
    <div class="insight"><strong>Insight:</strong> Discounted transactions represent a meaningful share of revenue (~38% of orders). However, profit margins compress as discount depth increases. The 11–15% discount band shows a notable margin drop, suggesting diminishing returns beyond moderate promotional levels.</div>
    <h3>Discount Band Breakdown</h3>
    <table>
      <tr><th>Discount Band</th><th>Avg Revenue</th><th>Avg Profit</th><th>Avg Margin</th><th>Avg Qty</th><th>Order Count</th></tr>
'''

for row in data['discount_analysis']:
    html += f'      <tr><td>{row["discount_bin"]}</td><td>${row["revenue"]:.2f}</td><td>${row["profit"]:.2f}</td><td>{row["profit_margin"]:.1f}%</td><td>{row["quantity"]:.1f}</td><td>{row["order_count"]:,}</td></tr>\n'

html += f'''    </table>
  </section>

  <!-- Customer Behavior & Loyalty Insights -->
  <section>
    <h2>Customer Behavior & Loyalty Insights</h2>
    <p class="muted">Examination of purchasing patterns by customer segment. <em>Note: Customer demographics (age, gender, loyalty membership) are not present in the provided dataset and would require joining with the customers dimension table for full segmentation analysis.</em></p>
    <div class="chart"><img src="data:image/png;base64,{charts['customer_loyalty']}" alt="Customer Loyalty"></div>
    <div class="insight"><strong>Insight:</strong> Repeat customers (2+ orders) represent {data['customer_stats']['repeat_pct']}% of the customer base but generate substantially higher lifetime revenue per customer. Retention and repeat-purchase programs are likely high-ROI investments.</div>
    <h3>Customer Segment Summary</h3>
    <table>
      <tr><th>Segment</th><th>Customers</th><th>Avg Lifetime Revenue</th><th>Avg Lifetime Profit</th><th>Avg Margin</th></tr>
'''

for row in data['loyalty']:
    html += f'      <tr><td>{row["customer_type"]}</td><td>{row["customer_count"]:,}</td><td>${row["total_revenue"]:.2f}</td><td>${row["total_profit"]:.2f}</td><td>{row["profit_margin"]:.1f}%</td></tr>\n'

html += f'''    </table>
    <div class="insight"><strong>Strategic Note:</strong> With {data['customer_stats']['total_customers']:,} unique customers in the dataset, increasing the repeat-customer rate from {data['customer_stats']['repeat_pct']:.1f}% to even 35–40% could materially lift total revenue without proportional customer acquisition cost.</div>
  </section>

  <footer>
    Report generated from 50,000 transaction records (2023–2024). All figures derived directly from data.csv.<br>
    For deeper product, store, and customer segmentation, join with the provided dimension tables.
  </footer>
</div>
</body>
</html>
'''

with open('output/final_report.html', 'w') as f:
    f.write(html)

print('Report written to output/final_report.html')
PYEOF
